#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>
#include <assert.h>
#include "../src/part_command.h"
int main(void){
    const wchar_t *valid[]={L"SKETCH_MOVE PRT1 SK1 0 -3 4",L"SKETCH_REMOVE PRT1 SK1 ENTITY 0",L"SKETCH_REMOVE PRT1 SK1 DIMENSION 0",L"SKETCH_REMOVE PRT1 SK1 CONSTRAINT 0",L"SKETCH_PROJECT PRT1 SK1 EDGE:70",L"SKETCH_PROJECT PRT1 SK1 CURVE:CV1",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 10 POS",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 10 NEG",L"SOLID_EXTRUDE PRT1 C1 SK1 CUT BLIND 3 POS",L"SOLID_EXTRUDE PRT1 C1 SK1 CUT THROUGH 0 NEG",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 360 POS",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 0.01 NEG"};
    const wchar_t *invalid[]={L"SKETCH_MOVE PRT1 SK1 0 nan 4",L"SKETCH_MOVE PRT1 SK1 0 3",L"SKETCH_REMOVE PRT1 SK1 ENT 0",L"SKETCH_REMOVE PRT1 SK1 ENTITY -1",L"SKETCH_PROJECT PRT1 SK1 EDGE:-1",L"SKETCH_PROJECT PRT1 SK1 ../edge",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD THROUGH 0 POS",L"SOLID_EXTRUDE PRT1 E1 SK1 CUT THROUGH 5 POS",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 0 POS",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 10 SIDE3",L"SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 1000001 POS",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 361 POS",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 0 POS",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 180 BOTH",L"SOLID_REVOLVE PRT1 R1 SK1 AXIS:AX1 inf POS"};
    PartCommand cmd;wchar_t p[1024];int i;
    for(i=0;i<sizeof(valid)/sizeof(valid[0]);i++){swprintf_s(p,1024,L"CREO_OP %ls",valid[i]);assert(part_command_parse(p,&cmd)==1&&cmd.verb==PART_FOUNDATION);}
    for(i=0;i<sizeof(invalid)/sizeof(invalid[0]);i++){swprintf_s(p,1024,L"CREO_OP %ls",invalid[i]);assert(part_command_parse(p,&cmd)==-1&&cmd.verb==PART_NONE);}
    assert(part_command_parse(L"CREO_OP SOLID_EXTRUDE PRT1 E1 SK1 ADD BLIND 10 POS\nCREO_OP SAVE PRT1",&cmd)==-1);
    puts("SOLID PROTOCOL: 12 valid, 15 invalid and mixed-command rejection PASS");return 0;
}
